func rotate(matrix [][]int) {
	n := len(matrix)
	// 深拷贝 matrix -> tmp
	tmp := make([][]int, n)
	for i := range tmp {
		tmp[i] = make([]int, n)
		copy(tmp[i], matrix[i])
	}
	// 根据元素旋转公式，遍历修改原矩阵 matrix 的各元素
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			matrix[j][n-1-i] = tmp[i][j]
		}
	}
}

func rotate(matrix [][]int) {
	// 设矩阵行列数为 n
	n := len(matrix)
	// 起始点范围为 0 <= i < n / 2 , 0 <= j < (n + 1) / 2
	for i := 0; i < n/2; i++ {
		for j := 0; j < (n+1)/2; j++ {
			// 暂存 A 至 tmp
			tmp := matrix[i][j]
			// 元素旋转操作 A <- D <- C <- B <- tmp
			matrix[i][j] = matrix[n-1-j][i]
			matrix[n-1-j][i] = matrix[n-1-i][n-1-j]
			matrix[n-1-i][n-1-j] = matrix[j][n-1-i]
			matrix[j][n-1-i] = tmp
		}
	}
}
